import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export interface Job {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, next_run_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_status_created ON jobs(status, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id));
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), seen_at INTEGER NOT NULL);`);
  return db;
}

export function fromRow(row: Record<string, unknown>): Job {
  return {
    id: String(row.id), status: row.status as Job['status'], input: String(row.input),
    steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: row.result_output == null ? null : { output: String(row.result_output) },
    error: row.error == null ? null : String(row.error), createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export const JOB_SELECT = `SELECT id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at FROM jobs`;
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, JOB_SELECT, fromRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer exists. Requeue it on startup;
// attempts already recorded still count toward the three-attempt limit.
db.exec('BEGIN IMMEDIATE');
try {
  db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_run_at=0 WHERE status='running'`)
    .run(new Date().toISOString());
  db.exec('COMMIT');
} catch (e) { db.exec('ROLLBACK'); throw e; }

function heartbeat(): void {
  db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
}
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 750);
console.log('worker started');

while (!stopping) {
  let job;
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`${JOB_SELECT} WHERE status='queued' AND next_run_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as Record<string, unknown> | undefined;
    if (row) {
      if (Number(row.attempts) >= 3) {
        db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?`).run(new Date().toISOString(), String(row.id));
      } else {
        db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, result_output=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'`)
          .run(new Date().toISOString(), String(row.id));
        job = fromRow(db.prepare(`${JOB_SELECT} WHERE id=?`).get(String(row.id)) as Record<string, unknown>);
      }
    }
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  if (!job) { await sleep(100); continue; }

  let failed = false;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (step === 1 && job.attempts <= job.failAttempts) { failed = true; break; }
    const updated = new Date().toISOString();
    db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`).run(step, updated, job.id);
  }
  const now = new Date().toISOString();
  if (failed) {
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', progress_completed=0, result_output=NULL, error='transient failure', updated_at=? WHERE id=? AND status='running'`).run(now, job.id);
    } else {
      // Backoff is comfortably within the required retry window.
      db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, result_output=NULL, error=NULL, next_run_at=?, updated_at=? WHERE id=? AND status='running'`).run(Date.now() + 500, now, job.id);
    }
  } else {
    db.prepare(`UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'`).run(job.input.toUpperCase(), now, job.id);
  }
}

clearInterval(heartbeatTimer);
db.close();
