import { openDatabase, fromRow, JOB_SELECT } from './dist/db.js';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
const path = '/tmp/job-tracker-review-recovery.db';
const db = openDatabase(path);
const input = 'a\\u0000\\ud800b';
const id = 'recovery-check';
db.prepare("'`INSERT INTO jobs(id,status,input,input_json,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,next_run_at,resume_attempt) VALUES(?, '"'running', '', ?, 3, 2, 3, 2, ?, ?, 0, 0)"'`)
  .run(id, JSON.stringify(input), new Date().toISOString(), new Date().toISOString());
const proc = spawn(process.execPath, ['"'--disable-warning=ExperimentalWarning', 'dist/worker.js'], { env: { ...process.env, DATABASE_PATH: path }, stdio: 'ignore' });
let row;
for (let i=0;i<60;i++) {
  await sleep(100);
  row = db.prepare("'`${JOB_SELECT} WHERE id=?`).get(id);
  if (row?.status === '"'completed') break;
}
if (row?.status "'!== '"'completed') throw new Error("'`Expected completion, got ${row?.status}`);
const job = fromRow(row);
if (job.input !== input || job.attempts !== 3 || job.progress.completed !== 3 || job.result?.output !== input.toUpperCase()) throw new Error('"'Recovery or lossless string check failed');
proc.kill('SIGTERM');
await new Promise(resolve => proc.once('exit', resolve));
db.close();
console.log('recovery and lossless string checks passed');
EOF"

